$root = Split-Path -Parent $PSScriptRoot
$out = Join-Path $root 'research\smoke_tests\prepilot-final-20260819'
$manifest = Get-Content (Join-Path $root 'research\smoke_tests\prepilot-final-20260819\manifest.json') -Raw | ConvertFrom-Json
$agents = @('syndrome','herbal','acupuncture_meridian','constitution','dietary_therapy','lifestyle_yangsheng')
$judges = @('evidence','hallucination','safety','conflict','confidence','provenance')
$results = @()
foreach ($item in $manifest.questions) {
  foreach ($condition in @('C1','C2')) {
    $payload = @{ question=$item.question; condition_id=$condition; retrieval_strategy='R0'; active_agents=$agents; active_judges=$judges; top_k=4; debate_rounds=1; include_trace=$true } | ConvertTo-Json -Depth 8
    $sw = [Diagnostics.Stopwatch]::StartNew(); $rec = [ordered]@{ smoke_id=$item.smoke_id; question=$item.question; expected_domain=$item.expected_main_domain; condition=$condition; retrieval='R0'; expected_chunk_ids=($item.expected_chunk_ids -join ';'); expected_multiple_specialists=$item.multiple_specialists_expected }
    try {
      $data = Invoke-RestMethod -Method Post -Uri 'http://127.0.0.1:8000/api/research/run' -ContentType 'application/json' -Body $payload -TimeoutSec 180; $sw.Stop(); $trace=$data.trace
      $answer = [string]$data.final_answer; $evidence=@($data.retrieval); $ids=@($evidence | ForEach-Object {$_.chunk_id}); $citations=@([regex]::Matches($answer,'\[(tcmv1-[0-9a-f]+)\]') | ForEach-Object {$_.Groups[1].Value} | Select-Object -Unique)
      $validIds = $true; $citeOk = ($citations.Count -gt 0); $malformed = ($answer.IndexOf([char]0xfffd) -ge 0); $quality = ($answer.Trim().Length -gt 0 -and !$malformed -and $validIds -and $citeOk)
      $fail=@(); if($trace.corpus_name -ne 'TCM Research Corpus v1' -or [int]$trace.corpus_chunk_count -ne 4461){$fail+='corpus metadata'}; if([int]$trace.provider_calls -gt 0 -and $trace.model -ne 'Qwen/Qwen3-8B'){$fail+='actual model'}; if([int]$trace.provider_calls -gt 0 -and $trace.provider -ne 'siliconflow'){$fail+='provider'}; if([int]$trace.provider_calls -ne [int]$trace.successful_provider_calls){$fail+='provider failure'}; if([int]$trace.provider_calls -gt 0 -and $trace.generation_mode -ne 'llm'){$fail+='generation mode'}; if($trace.fallback_usage){$fail+='fallback'}; if(!$quality){$fail+='output quality/citations'}; if($evidence.Count -eq 0){$fail+='no retrieved evidence'}
      $rec.run_id=$data.run_id; $rec.model=$trace.model; $rec.provider_attempted=[int]$trace.provider_calls; $rec.provider_succeeded=[int]$trace.successful_provider_calls; $rec.generation_mode=$trace.generation_mode; $rec.fallback=[bool]$trace.fallback_usage; $rec.latency_ms=[int]$trace.latency_ms; $rec.participating_agents=(@($trace.participating_agents) -join ';'); $rec.abstaining_agents=(@($trace.abstaining_agents) -join ';'); $rec.evidence_count=$evidence.Count; $rec.output_quality_pass=$quality; $rec.trace=($trace | ConvertTo-Json -Compress); $rec.evidence_ids=($ids -join ';'); $rec.citation_ids=($citations -join ';'); $rec.answer=$answer; if($trace.generation_mode -eq 'abstention' -and $evidence.Count -eq 0){if($item.expected_chunk_ids){$rec.classification='FAIL_ROUTING'}else{$rec.classification='CORRECT_ABSTENTION'}}elseif($trace.generation_mode -eq 'llm' -and !$trace.fallback_usage -and $quality){if([int]$trace.provider_calls -gt [int]$trace.successful_provider_calls){$rec.classification='PASS_WITH_RETRY'}else{$rec.classification='PASS'}}elseif($trace.fallback_usage){$rec.classification='FAIL_PROVIDER'}elseif(!$quality){$rec.classification='FAIL_OUTPUT_QUALITY'}else{$rec.classification='COVERAGE_GAP'}; if($rec.classification -like 'PASS*'){$rec.run_status='PASS'}else{$rec.run_status='FAIL'}; $rec.failure_reason=($fail -join '; ')
    } catch { $sw.Stop(); $rec.run_status='FAIL'; $rec.failure_reason="API exception: $($_.Exception.Message)"; $rec.output_quality_pass=$false; $rec.client_latency_ms=[int]$sw.ElapsedMilliseconds }
    $results += [pscustomobject]$rec; Write-Host "$($item.smoke_id) $condition $($rec.run_status) $($rec.latency_ms)ms"
  }
}
$results | ConvertTo-Json -Depth 12 | Set-Content (Join-Path $out 'results.json') -Encoding UTF8
$results | Select-Object smoke_id,question,expected_domain,condition,retrieval,model,participating_agents,provider_attempted,provider_succeeded,generation_mode,fallback,latency_ms,evidence_count,output_quality_pass,classification,run_status,failure_reason | Export-Csv (Join-Path $out 'summary.csv') -NoTypeInformation -Encoding UTF8
$summary=[ordered]@{total_runs=$results.Count;passed_runs=@($results|? run_status -eq PASS).Count;failed_runs=@($results|? run_status -ne PASS).Count;fallback_runs=@($results|? fallback).Count;provider_failures=@($results|? failure_reason -match 'provider failure').Count;corrupted_outputs=@($results|? failure_reason -match 'output quality').Count}
foreach($c in @('C1','C2')){$v=@($results|? condition -eq $c|? latency_ms|% {[double]$_.latency_ms});$summary["${c}_mean_latency_ms"] = if($v){[math]::Round(($v|Measure-Object -Average).Average,1)}else{$null};$summary["${c}_median_latency_ms"] = if($v){[math]::Round(($v|Sort-Object|Select-Object -Index ([math]::Floor($v.Count/2))),1)}else{$null}}
$summary | ConvertTo-Json | Set-Content (Join-Path $out 'summary.json') -Encoding UTF8; $summary | ConvertTo-Json
